import attr
from typing import Optional
from .gnb.networkaddress import NetworkAddress
from .connection_details import SshServiceDetails


@attr.s(cmp=False)
class PxeServer(object):
    """
    :param Optional[NetworkAddress] nfs_ip:
    :param Optional[SshServiceDetails] ssh_connection_details:
    """
    nfs_ip = attr.ib(default=None, type=Optional[NetworkAddress])
    ssh_connection_details = attr.ib(default=None, type=Optional[SshServiceDetails])

    def __taf_contract_ssh__(self):
        return self.ssh_connection_details.__taf_contract_ssh__()


@attr.s(cmp=False)
class Velocity(object):
    """
    Spirent Velocity tool configuration

    :param Optional[NetworkAddress] addr:
    """
    addr = attr.ib(type=NetworkAddress)
    topology_name = attr.ib(default=None, type=Optional[str])
